    "Уровень сахара (0–10):": { kk:"Қант мөлшері (0–10):", ky:"Кант деңгээли (0–10):", az:"Şəkər səviyyəsi (0–10):" },
    "Растительное молоко": { kk:"Өсімдік сүті", ky:"Өсүмдүк сүтү", az:"Bitki mənşəli süd" },
